events = [
    {"op": "r", "key": 1, "after": {"id": 1, "bal": 100}, "pos": 10},
    {"op": "c", "key": 2, "after": {"id": 2, "bal": 50},  "pos": 11},
    {"op": "u", "key": 1, "after": {"id": 1, "bal": 70},  "pos": 12},
    {"op": "u", "key": 1, "after": {"id": 1, "bal": 70},  "pos": 12},  # 다시 온 이벤트
    {"op": "d", "key": 2, "after": None,                  "pos": 13},
    {"op": "u", "key": 1, "after": {"id": 1, "bal": 100}, "pos": 10},  # 늦게 온 옛 이벤트
]
table, last_pos = {}, {}
for e in events:
    k = e["key"]
    if last_pos.get(k, -1) >= e["pos"]:
        print("skip", e["op"], "key", k, "pos", e["pos"])
        continue
    last_pos[k] = e["pos"]
    if e["op"] == "d":
        table.pop(k, None)
    else:
        table[k] = e["after"]
print(table)
# skip u key 1 pos 12
# skip u key 1 pos 10
# {1: {'id': 1, 'bal': 70}}
